create extension if not exists pgcrypto;
create type public.rating as enum('again','hard','good','easy');
create table public.profiles(id uuid primary key references auth.users on delete cascade,display_name text not null default '',coin_balance int not null default 0,created_at timestamptz not null default now());
create table public.material_decks(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,title text not null,subject text,description text,is_public boolean not null default false,share_token text not null unique default gen_random_uuid()::text,created_at timestamptz not null default now());
create table public.material_nodes(id uuid primary key default gen_random_uuid(),deck_id uuid not null references material_decks on delete cascade,parent_id uuid references material_nodes on delete cascade,node_type text not null check(node_type in('folder','item')),title text not null,memo text,order_index int not null default 0,created_at timestamptz not null default now());
create table public.material_item_states(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,material_node_id uuid not null references material_nodes on delete cascade,last_rating rating,unknown_flag boolean not null default false,review_count int not null default 0,due_at timestamptz,next_review_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,material_node_id));
create table public.material_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,material_node_id uuid not null references material_nodes on delete cascade,rating rating not null,unknown_flag boolean not null default false,reviewed_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.word_lists(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,title text not null,subject text,description text,is_public boolean not null default false,share_token text not null unique default gen_random_uuid()::text,created_at timestamptz not null default now());
create table public.word_cards(id uuid primary key default gen_random_uuid(),list_id uuid not null references word_lists on delete cascade,card_id text,front text not null,back text not null,memo text,order_index int not null default 0,created_at timestamptz not null default now());
create table public.word_card_states(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,word_card_id uuid not null references word_cards on delete cascade,last_rating rating,unknown_flag boolean not null default false,review_count int not null default 0,due_at timestamptz,next_review_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,word_card_id));
create table public.word_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,word_card_id uuid not null references word_cards on delete cascade,rating rating not null,unknown_flag boolean not null default false,reviewed_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.item_resources(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,target_type text not null check(target_type in('material_item','word_card')),target_id uuid not null,url text not null,title text,note text,created_at timestamptz not null default now());
create table public.coin_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,amount int not null,reason text not null,created_at timestamptz not null default now());
create or replace function public.handle_new_user()returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,display_name)values(new.id,coalesce(new.raw_user_meta_data->>'display_name',''));return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.review_target(p_type text,p_id uuid,p_rating rating,p_unknown boolean)returns void language plpgsql security definer set search_path=public as $$declare days int:=case p_rating when'again'then 0 when'hard'then 1 when'good'then 3 else 7 end;begin if p_type='material' then if not exists(select 1 from material_nodes n join material_decks d on d.id=n.deck_id where n.id=p_id and n.node_type='item'and d.user_id=auth.uid())then raise exception'not allowed';end if;insert into material_item_states(user_id,material_node_id,last_rating,unknown_flag,review_count,due_at,next_review_date)values(auth.uid(),p_id,p_rating,p_unknown,1,now()+make_interval(days=>days),current_date+days)on conflict(user_id,material_node_id)do update set last_rating=p_rating,unknown_flag=p_unknown,review_count=material_item_states.review_count+1,due_at=now()+make_interval(days=>days),next_review_date=current_date+days,updated_at=now();insert into material_attempts(user_id,material_node_id,rating,unknown_flag)values(auth.uid(),p_id,p_rating,p_unknown);else if not exists(select 1 from word_cards c join word_lists l on l.id=c.list_id where c.id=p_id and l.user_id=auth.uid())then raise exception'not allowed';end if;insert into word_card_states(user_id,word_card_id,last_rating,unknown_flag,review_count,due_at,next_review_date)values(auth.uid(),p_id,p_rating,p_unknown,1,now()+make_interval(days=>days),current_date+days)on conflict(user_id,word_card_id)do update set last_rating=p_rating,unknown_flag=p_unknown,review_count=word_card_states.review_count+1,due_at=now()+make_interval(days=>days),next_review_date=current_date+days,updated_at=now();insert into word_attempts(user_id,word_card_id,rating,unknown_flag)values(auth.uid(),p_id,p_rating,p_unknown);end if;end$$;
do $$declare t text;begin foreach t in array array['profiles','material_decks','material_nodes','material_item_states','material_attempts','word_lists','word_cards','word_card_states','word_attempts','item_resources','coin_transactions']loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy "profile own" on profiles for all using(id=auth.uid())with check(id=auth.uid());
create policy "material decks own" on material_decks for all using(user_id=auth.uid())with check(user_id=auth.uid());
create policy "material nodes own" on material_nodes for all using(exists(select 1 from material_decks d where d.id=deck_id and d.user_id=auth.uid()))with check(exists(select 1 from material_decks d where d.id=deck_id and d.user_id=auth.uid()));
create policy "material decks public read" on material_decks for select using(is_public);
create policy "material nodes public read" on material_nodes for select using(exists(select 1 from material_decks d where d.id=deck_id and d.is_public));
create policy "material states own" on material_item_states for select using(user_id=auth.uid());create policy "material attempts own" on material_attempts for select using(user_id=auth.uid());
create policy "word lists own" on word_lists for all using(user_id=auth.uid())with check(user_id=auth.uid());
create policy "word cards own" on word_cards for all using(exists(select 1 from word_lists l where l.id=list_id and l.user_id=auth.uid()))with check(exists(select 1 from word_lists l where l.id=list_id and l.user_id=auth.uid()));
create policy "word lists public read" on word_lists for select using(is_public);
create policy "word cards public read" on word_cards for select using(exists(select 1 from word_lists l where l.id=list_id and l.is_public));
create policy "word states own" on word_card_states for select using(user_id=auth.uid());create policy "word attempts own" on word_attempts for select using(user_id=auth.uid());
create policy "resources own" on item_resources for all using(user_id=auth.uid())with check(user_id=auth.uid());create policy "coins own" on coin_transactions for select using(user_id=auth.uid());
create or replace function public.copy_shared_material(p_token text)returns uuid language plpgsql security definer set search_path=public as $$declare source_id uuid;new_deck uuid;n record;new_node uuid;node_map jsonb:='{}';begin if auth.uid()is null then raise exception'login required';end if;select id into source_id from material_decks where share_token=p_token and is_public;if source_id is null then raise exception'not found';end if;insert into material_decks(user_id,title,description)select auth.uid(),title,description from material_decks where id=source_id returning id into new_deck;for n in with recursive tree as(select mn.*,0 depth from material_nodes mn where deck_id=source_id and parent_id is null union all select child.*,tree.depth+1 from material_nodes child join tree on child.parent_id=tree.id)select*from tree order by depth,order_index loop insert into material_nodes(deck_id,parent_id,node_type,title,memo,order_index)values(new_deck,case when n.parent_id is null then null else(node_map->>n.parent_id::text)::uuid end,n.node_type,n.title,n.memo,n.order_index)returning id into new_node;node_map:=node_map||jsonb_build_object(n.id::text,new_node::text);end loop;return new_deck;end$$;
create or replace function public.copy_shared_cards(p_token text)returns uuid language plpgsql security definer set search_path=public as $$declare source_id uuid;new_list uuid;begin if auth.uid()is null then raise exception'login required';end if;select id into source_id from word_lists where share_token=p_token and is_public;if source_id is null then raise exception'not found';end if;insert into word_lists(user_id,title,description)select auth.uid(),title,description from word_lists where id=source_id returning id into new_list;insert into word_cards(list_id,card_id,front,back,memo,order_index)select new_list,card_id,front,back,memo,order_index from word_cards where list_id=source_id;return new_list;end$$;
